function emptyData(){return {schools:schoolNames.map((name,i)=>({id:i+1,name,province:provinces[i],unit_type:i===7?'institute':'college'})),personnel:[],documents:[],certificates:[],document_types:[],lookups:[],settings:[],status_history:[],personnel_changes:[],personnel_requests:[],profiles:[],archived_personnel:[],audit_log:[],school_assignments:[],administration_changes:[]};}
