function changeValue(key,value){
 if(key==='school_id')return school(value);
 if(key==='avatar_data')return value?'มีรูปโปรไฟล์':'ไม่มีรูป';
 if(Array.isArray(value))return value.join(' / ')||'—';
 if(['birth_date','start_date','retirement_override','deleted_at'].includes(key))return date(value);
 return String(value??'').trim()||'—';
}
function changesTable(changes){return table(['ข้อมูลที่เปลี่ยน','ค่าเดิม','ค่าใหม่'],changes.map(c=>[esc(c.label),esc(changeValue(c.key,c.before)),esc(c.key==='avatar_data'&&c.before&&c.after?'อัปเดตรูปโปรไฟล์':changeValue(c.key,c.after))]));}
function reviewPersonnel(form,row,certificate){
 const before=editSnapshot||{},changes=personnelDiff(before,row);
 if(!changes.length&&!certificate)throw Error('ยังไม่มีการเปลี่ยนแปลงข้อมูล');
 const previousReason=pendingChange?.reason||'';
 pendingChange={row,certificate,expectedRevision:before.revision??null,before,form,reason:previousReason,title:row.id?'แก้ไขข้อมูลบุคลากร':'เพิ่มบุคลากร'};
 const p={...before,...row};
 modal('ตรวจสอบข้อมูลก่อนบันทึก',`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>เลขที่ตำแหน่ง ${esc(p.employee_code)} · ${esc(school(p.school_id))}</span></div>${changes.some(c=>c.key==='avatar_data')?photoComparison(before.avatar_data,row.avatar_data):''}${changes.length?changesTable(changes):'<p>ข้อมูลบุคลากรคงเดิม เพิ่มเฉพาะใบรับรองด้านล่าง</p>'}${certificate?`<section class="review-certificate"><h3>ใบรับรองที่จะเพิ่มพร้อมกัน</h3>${table(['ข้อมูล','รายละเอียด'],Object.entries({ประเภท:certKinds[certificate.kind],ชื่อใบรับรอง:certificate.name,หน่วยงานผู้ออก:certificate.issuer,สาขาอาชีพ:certificate.occupation||'—',ระดับสมรรถนะ:certificate.competency_level||'—',มาตรฐานอ้างอิง:certificate.standard||'—',เลขที่:certificate.number||'—',วันที่ออก:date(certificate.issued_on),วันหมดอายุ:date(certificate.expires_on)}).map(([k,v])=>[esc(k),esc(v)]))}</section>`:''}<form id="personreviewform" class="formgrid"><label class="wide">${row.id?'เหตุผลการแก้ไข *':'หมายเหตุ'}<textarea name="reason" rows="2" maxlength="1000" ${row.id?'required minlength="5"':''}>${esc(row.id?previousReason:'เพิ่มบุคลากร')}</textarea></label><label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบบุคคล สถานศึกษา และข้อมูลข้างต้นแล้ว</span></label><div class="wide error" id="formerror" hidden></div><div class="wide modalactions"><button type="button" data-action="backpersonreview">ย้อนกลับแก้ไข</button><button type="submit" class="primary">${icon('check')}<span>ยืนยันบันทึก${row.id?'การแก้ไข':'บุคลากร'}</span></button></div><p class="wide footnote">หากมีผู้อื่นแก้ไขข้อมูลก่อนยืนยัน ระบบจะให้ตรวจข้อมูลล่าสุดอีกครั้ง ${btn('ยกเลิกร่างและโหลดใหม่','reloadperson','','rowbtn')}</p></form>`);
}
function backPersonReview(){
 if(!pendingChange)return;
 pendingChange.reason=$('#personreviewform textarea[name="reason"]')?.value||'';
 const draft=pendingChange;modal(draft.title,'<div id="personformreturn"></div>');$('#personformreturn').replaceWith(draft.form);activePerson=draft.row.id||'';editSnapshot=draft.before;
}
function lifecyclePerson(id,operation){
 if(!isAdmin())throw Error('เฉพาะผู้ดูแลระบบ');
 const p=(operation==='delete'?data.personnel:data.archived_personnel).find(p=>p.id===id);if(!p)throw Error('ไม่พบข้อมูล กรุณาโหลดรายชื่อใหม่');
 pendingLifecycle={person:structuredClone(p),operation};pendingChange=null;
 const removing=operation==='delete';
 modal(removing?'ตรวจสอบก่อนลบบุคลากร':'ตรวจสอบก่อนกู้คืนบุคลากร',`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>เลขที่ตำแหน่ง ${esc(p.employee_code)}</span><span>${esc(school(p.school_id))} · ${esc(p.position)}</span></div><p class="${removing?'warning':'notice'}">${removing?'รายการนี้จะย้ายไปเมนู “รายการที่ลบ” และไม่นับในภาพรวม รายงาน หรือรายการรอตรวจ เอกสารและใบรับรองยังเก็บไว้และผู้ดูแลกู้คืนได้':'รายการนี้จะกลับเข้าทะเบียนพร้อมเอกสารและใบรับรองเดิม และนับรวมในภาพรวมอีกครั้ง'}</p><form id="lifecycleform" class="formgrid">${input('confirm_code','กรอกเลขที่ตำแหน่งของบุคลากรนี้ซ้ำเพื่อยืนยัน *','','text','required autocomplete="off" maxlength="50"')}<label class="wide">เหตุผล${removing?'การลบ':'การกู้คืน'} *<textarea name="reason" rows="3" minlength="5" maxlength="1000" required></textarea></label><label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบชื่อ เลขที่ตำแหน่ง และสถานศึกษาถูกต้องแล้ว</span></label><div class="wide error" id="formerror" hidden></div><div class="wide modalactions"><button type="button" data-action="close">ยกเลิก</button><button type="submit" class="${removing?'danger-solid':'primary'}">${icon(removing?'trash':'refresh')}<span>${removing?'ยืนยันลบบุคลากร':'ยืนยันกู้คืนบุคลากร'}</span></button></div><p class="wide footnote">${btn('ยกเลิกร่างและโหลดใหม่','reloadperson','','rowbtn')}</p></form>`);
}
function archive(){
 if(!isAdmin())return accessLocked();
 const rows=data.archived_personnel.filter(p=>(!filters.school||p.school_id==filters.school)&&(!filters.q||`${p.full_name} ${p.employee_code}`.toLowerCase().includes(filters.q.toLowerCase())));
 return head('รายการบุคลากรที่ลบ','ตรวจสอบเหตุผลและประวัติ แล้วกู้คืนรายบุคคลได้',btn('กลับทะเบียน','goto','data-page="personnel"'))+`<section class="panel"><p class="footnote">เอกสารและใบรับรองยังเก็บไว้ เลขที่ตำแหน่งเดิมยังถูกสงวนเพื่อให้กู้คืนได้ หากต้องใช้รายการเดิมให้กู้คืนแทนการสร้างซ้ำ</p>${filterUI()}${table(['บุคลากร','หน่วยงาน/สถานศึกษา','วันที่ลบ','เหตุผล','จัดการ'],rows.map(p=>[namecell(p),esc(school(p.school_id)),date(p.deleted_at),esc(p.delete_reason),`<div class="person-actions">${btn('ประวัติ','personhistory',`data-id="${esc(p.id)}"`,'rowbtn')}${btn('กู้คืน','restoreperson',`data-id="${esc(p.id)}"`,'rowbtn')}</div>`]))}<p class="footnote">${rows.length} จาก ${data.archived_personnel.length} รายการ</p></section>`;
}
function personHistory(id){
 const p=[...data.personnel,...(data.archived_personnel||[])].find(p=>p.id===id);if(!p)throw Error('ไม่พบข้อมูลบุคลากร');
 const actions={CREATE:'เพิ่มบุคลากร',UPDATE:'แก้ไขข้อมูล',DELETE:'ลบบุคลากร',RESTORE:'กู้คืนบุคลากร',BASELINE:'ข้อมูลก่อนอัปเกรด'};
 const rows=data.personnel_changes.filter(h=>h.personnel_id===id).sort((a,b)=>b.revision-a.revision);
 modal('ประวัติการเปลี่ยนแปลงบุคลากร',`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>${esc(p.employee_code)} · ${esc(school(p.school_id))}${p.deleted_at?' · อยู่ในรายการที่ลบ':''}</span></div><p class="footnote">ประวัติครอบคลุมการเปลี่ยนแปลงตั้งแต่ติดตั้งรุ่น 1.6 ไม่เก็บภาพโปรไฟล์ซ้ำในประวัติ</p><div class="change-timeline">${rows.slice(0,100).map(h=>`<details class="change-entry"><summary><strong>${esc(actions[h.action]||h.action)} · รุ่น ${h.revision}</strong><span>${new Date(h.changed_at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</span></summary><p><b>เหตุผล:</b> ${esc(h.reason)}</p><p class="footnote">ผู้ดำเนินการ: ${esc(({admin:'ผู้ดูแลระบบ',personnel:'บุคลากร',school_editor:'เจ้าหน้าที่หน่วยงาน',system:'ระบบ'})[h.actor_role]||h.actor_role)} · ${esc(h.actor_id||'ระบบ')}</p>${changesTable(personnelDiff(h.old_data,h.new_data))}</details>`).join('')||'<p class="muted">ยังไม่มีประวัติการเปลี่ยนแปลง</p>'}</div>${rows.length>100?'<p class="footnote">แสดง 100 รุ่นล่าสุด ประวัติทั้งหมดเก็บในฐานข้อมูลและสำเนาสำรอง</p>':''}`);
}

function openLogin(){modal('เข้าสู่ระบบ HRVec-Andaman2',`<p class="subtitle">ใช้ชื่อผู้ใช้และรหัสผ่านที่แอดมินกำหนดให้ บัญชีเดิมที่ใช้อีเมลยังเข้าสู่ระบบได้</p><form id="loginform" class="formgrid">${input('email','ชื่อผู้ใช้ / อีเมลเดิม','','text','required autocomplete="username" autocapitalize="none" spellcheck="false"')}${input('password','รหัสผ่าน','','password','required autocomplete="current-password"')}${formEnd}</form>`);}
function passwordRequired(){return head('เปลี่ยนรหัสผ่านก่อนเริ่มใช้งาน','บัญชีใหม่หรือบัญชีที่แอดมินรีเซ็ตต้องกำหนดรหัสส่วนตัวก่อนเปิดข้อมูล')+`<section class="panel privacybox">${icon('shield')}<h2>กำหนดรหัสผ่านส่วนตัว</h2><p>ใช้รหัสเริ่มต้นที่ได้รับเป็นรหัสปัจจุบัน แล้วกำหนดรหัสใหม่อย่างน้อย 8 ตัวอักษร มีทั้งตัวอักษรและตัวเลข</p>${btn('เปลี่ยนรหัสผ่าน','changepassword','','primary')}${btn('ออกจากระบบ','signout')}</section>`;}
function passwordForm(){
 if(api.session().mode!=='live')throw Error('กรุณาเข้าสู่ระบบจริงก่อนเปลี่ยนรหัสผ่าน');
 modal(api.session().mustChangePassword?'เปลี่ยนรหัสผ่านครั้งแรก':'เปลี่ยนรหัสผ่าน',`<p>บัญชี ${esc(api.session().username||api.session().email)}</p><form id="passwordform" class="formgrid">${input('current_password','รหัสผ่านปัจจุบัน','','password','required autocomplete="current-password"')}${input('new_password','รหัสผ่านใหม่','','password','required minlength="8" autocomplete="new-password"')}${input('confirm_password','ยืนยันรหัสผ่านใหม่','','password','required minlength="8" autocomplete="new-password"')}<p class="wide footnote">อย่างน้อย 8 ตัวอักษร มีตัวอักษรและตัวเลข แตกต่างจากรหัสเดิม หลังเปลี่ยนสำเร็จให้เข้าสู่ระบบด้วยรหัสใหม่</p>${formEnd.replace('บันทึกข้อมูล','ยืนยันเปลี่ยนรหัสผ่าน')}</form>`);
}
function accountState(profile){return !profile?'ยังไม่มีบัญชี':profile.account_pending?'รอตรวจแก้การตั้งบัญชี':!profile.account_enabled?'พักบัญชี':profile.must_change_password?'รอเปลี่ยนรหัสครั้งแรก':'พร้อมใช้งาน';}
function accounts(){
 if(!isAdmin())return accessLocked();
 const rows=people();return head('จัดการบัญชีบุคลากร','กำหนดบัญชี รหัสเริ่มต้น และสิทธิ์เจ้าหน้าที่ตามสถานศึกษาที่รับผิดชอบ')+`<div class="account-schools">${data.schools.map(s=>{const ps=data.personnel.filter(p=>p.school_id===s.id),count=ps.filter(p=>p.user_id).length;return `<a href="${routeHref('accounts',{school:s.id})}" class="account-school"><span>${icon('school')}</span><strong>${esc(s.name)}</strong><small>มีบัญชี ${count} / ${ps.length} คน</small></a>`;}).join('')}</div><section class="panel">${api.session().mode==='demo'?'<p class="warning">กำลังดูข้อมูลสาธิต การสร้างบัญชีและเปลี่ยนรหัสจริงต้องติดตั้งระบบตามคู่มือ</p>':''}${filterUI()}${table(['บุคลากร','หน่วยงาน/สถานศึกษา','ชื่อผู้ใช้','บัญชี','จัดการ'],rows.map(p=>{const a=data.profiles.find(a=>a.id===p.user_id);return [namecell(p),esc(school(p.school_id)),esc(a?.username||(p.user_id?'บัญชีเดิม ใช้อีเมล':'—')),esc(accountState(a)),`<div class="person-actions">${!p.user_id?btn('สร้างบัญชี','accountform',`data-id="${esc(p.id)}"`,'rowbtn'):btn('รีเซ็ตรหัสผ่าน','accountform',`data-id="${esc(p.id)}" data-operation="reset_password"`,'rowbtn')+btn(a?.account_enabled===false?'เปิดบัญชี':'พักบัญชี','accountform',`data-id="${esc(p.id)}" data-operation="set_enabled"`,'rowbtn')}${p.user_id?btn('กำหนดสิทธิ์','assignpermissions',`data-id="${esc(p.id)}"`,'rowbtn'):''}</div>`];}))}${assignmentsPanel()}<p class="footnote">ผู้ใช้เปลี่ยนรหัสหลังเข้าใช้ครั้งแรก แอดมินกำหนดรหัสใหม่ได้ รหัสผ่านเดิมไม่แสดงในระบบหรือไฟล์ส่งออก</p></section>`;
}
function accountForm(id,operation=''){
 if(!isAdmin())throw Error('เฉพาะผู้ดูแลระบบ');const p=person(id);if(!p)throw Error('ไม่พบข้อมูลบุคลากร');const a=data.profiles.find(a=>a.id===p.user_id);
 operation=operation||(p.user_id?'reset_password':'create');if(p.user_id&&!a&&api.session().mode==='live')throw Error('กรุณาโหลดข้อมูลบัญชีใหม่');
 if(!['create','reset_password','set_enabled'].includes(operation))throw Error('คำสั่งไม่ถูกต้อง');
 accountTarget={person:structuredClone(p),profile:a?structuredClone(a):null,operation};
 const title=operation==='create'?'สร้างบัญชีบุคลากร':operation==='reset_password'?'กำหนดรหัสผ่านใหม่':a?.account_enabled===false?'เปิดใช้งานบัญชี':'พักการใช้งานบัญชี';
 modal(title,`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>${esc(p.employee_code)} · ${esc(school(p.school_id))}</span></div><form id="accountform" class="formgrid">${operation==='create'?input('username','ชื่อผู้ใช้ *',suggestedUsername(p),'text','required minlength="3" maxlength="50" autocomplete="off" autocapitalize="none" spellcheck="false"'):`<p class="wide">ชื่อผู้ใช้: <b>${esc(a?.username||'บัญชีเดิม ใช้อีเมล')}</b></p>`}${operation!=='set_enabled'?input('password','รหัสผ่านเริ่มต้นที่แอดมินกำหนด *','','password','required minlength="8" autocomplete="new-password"')+input('confirm_password','ยืนยันรหัสผ่าน *','','password','required minlength="8" autocomplete="new-password"')+'<p class="wide footnote">อย่างน้อย 8 ตัวอักษร มีตัวอักษรและตัวเลข ส่งมอบรหัสให้เจ้าของบัญชีผ่านช่องทางของหน่วยงาน ผู้ใช้ต้องเปลี่ยนรหัสก่อนเปิดข้อมูล</p>':'<p class="wide footnote">การเปลี่ยนสถานะบัญชีจะตัดสิทธิ์เซสชันเดิม ผู้ใช้ต้องเข้าสู่ระบบใหม่เมื่อเปิดบัญชี</p>'}<label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบบุคคล สถานศึกษา และบัญชีที่ต้องการจัดการแล้ว</span></label>${formEnd.replace('บันทึกข้อมูล','ยืนยัน'+title)}<p class="wide footnote">${btn('ยกเลิกร่างและโหลดบัญชีใหม่','reloadperson','','rowbtn')}</p></form>`);
}
function requests(){
 const states={pending:'รอแอดมินตรวจสอบ',approved:'อนุมัติลบแล้ว',rejected:'ไม่อนุมัติ / ส่งกลับ'};
 const rows=data.personnel_requests.filter(r=>{const p=person(r.personnel_id)||data.archived_personnel?.find(p=>p.id===r.personnel_id);return p&&(!filters.school||p.school_id==filters.school)&&(!filters.q||`${p.full_name} ${p.employee_code} ${r.reason}`.includes(filters.q));}).sort((a,b)=>b.created_at.localeCompare(a.created_at));
 return head(isAdmin()?'ตรวจสอบคำขอลบข้อมูล':'คำขอลบข้อมูลของฉัน',isAdmin()?'ตรวจบุคคล เหตุผล และรุ่นข้อมูลก่อนอนุมัติลบ':'ติดตามผลพิจารณาและเหตุผลจากแอดมิน')+`<section class="panel">${filterUI()}${table(['บุคลากร','หน่วยงาน/สถานศึกษา','คำขอ / วันที่','ผลพิจารณา','จัดการ'],rows.map(r=>{const p=person(r.personnel_id)||data.archived_personnel.find(p=>p.id===r.personnel_id);return [namecell(p),esc(school(p.school_id)),`${esc(r.reason)}<br><small>${date(r.created_at)}</small>`,`${esc(states[r.status]||r.status)}${r.review_reason?'<br><small>'+esc(r.review_reason)+'</small>':''}`,isAdmin()&&r.status==='pending'?`<div class="person-actions">${person(r.personnel_id)?btn('ตรวจและอนุมัติ','reviewremoval',`data-id="${esc(r.id)}" data-decision="approve"`,'rowbtn danger'):''}${btn('ไม่อนุมัติ','reviewremoval',`data-id="${esc(r.id)}" data-decision="reject"`,'rowbtn')}</div>`:'—'];}))}</section>`;
}
function removalForm(id){
 const p=person(id);if(!p||!access(p,'request_delete'))throw Error('ไม่มีสิทธิ์ส่งคำขอลบ');if(data.personnel_requests.some(r=>r.personnel_id===id&&r.status==='pending')){location.hash='#requests';$('#modal').close();return;}
 requestTarget=structuredClone(p);modal('ส่งคำขอลบข้อมูลบุคลากร',`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>${esc(p.employee_code)} · ${esc(school(p.school_id))}</span></div><p>คำขอนี้ส่งให้แอดมินพิจารณาก่อนลบ ระหว่างรอผล ข้อมูลยังอยู่ในทะเบียนใช้งาน</p><form id="removalrequestform" class="formgrid">${input('confirm_code','กรอกเลขที่ตำแหน่งซ้ำเพื่อยืนยัน *','','text','required autocomplete="off"')}<label class="wide">เหตุผลที่ขอลบข้อมูล *<textarea name="reason" minlength="5" maxlength="1000" rows="3" required></textarea></label><label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบบุคคลและต้องการส่งคำขอนี้ให้แอดมิน</span></label>${formEnd.replace('บันทึกข้อมูล','ส่งคำขอให้แอดมิน')}</form>`);
}
function reviewRemovalForm(id,decision){
 if(!isAdmin())throw Error('เฉพาะผู้ดูแลระบบ');const r=data.personnel_requests.find(r=>r.id===id&&r.status==='pending');if(!r)throw Error('ไม่พบคำขอที่รอพิจารณา');const p=person(r.personnel_id)||data.archived_personnel.find(p=>p.id===r.personnel_id);
 requestTarget={id,decision};modal(decision==='approve'?'ตรวจสอบก่อนอนุมัติลบ':'พิจารณาไม่อนุมัติคำขอ',`<div class="review-person"><strong>${esc(p?.full_name)}</strong><span>${esc(p?.employee_code)} · ${esc(school(p?.school_id))}</span></div><p>เหตุผลของผู้ขอ: ${esc(r.reason)}</p><p class="footnote">รุ่นข้อมูลตอนส่งคำขอ ${r.personnel_revision} · รุ่นปัจจุบัน ${p?.revision??'—'} ${decision==='approve'?'หากข้อมูลเปลี่ยนหลังส่งคำขอ ระบบจะให้ตรวจสอบและส่งคำขอใหม่ก่อนอนุมัติ':''}</p><form id="removalreviewform" class="formgrid"><label class="wide">เหตุผลการพิจารณา *<textarea name="reason" minlength="5" maxlength="1000" rows="3" required></textarea></label><label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจชื่อ สถานศึกษา เหตุผล และผลพิจารณาแล้ว</span></label>${formEnd.replace('บันทึกข้อมูล',decision==='approve'?'ยืนยันอนุมัติลบ':'ยืนยันไม่อนุมัติ')}</form>`);
}

function schoolsPanel(){
 return `<section class="panel settings-panel" id="settings-schools"><div class="paneltitle"><h2>หน่วยงานและสถานศึกษา</h2>${btn('เพิ่มหน่วยงาน/สถานศึกษา','schoolmanage','data-operation="create"','primary')}</div><p class="footnote">ปิดใช้งานเพื่อเก็บทะเบียนและประวัติเดิม การลบถาวรทำได้เฉพาะสถานศึกษาที่ไม่มีข้อมูลอ้างอิง</p>${table(['รหัส','หน่วยงาน/สถานศึกษา','ประเภท','จังหวัด','การใช้งาน','บุคลากร','จัดการ'],data.schools.map(s=>{const n=[...data.personnel,...data.archived_personnel].filter(p=>p.school_id===s.id).length,linked=data.school_assignments.some(a=>a.school_id===s.id);return [s.id,esc(s.name),unitType(s)==='institute'?'ส่วนกลางสถาบัน':'สถานศึกษา',esc(s.province),`<span class="tag ${s.is_active===false?'amber':'blue'}">${s.is_active===false?'ปิดใช้งาน':'ใช้งาน'}</span>`,n,`<div class="person-actions">${btn('แก้ไข','editschool',`data-id="${s.id}"`,'rowbtn')}${btn(s.is_active===false?'เปิดใช้งาน':'ปิดใช้งาน','schoolmanage',`data-id="${s.id}" data-operation="${s.is_active===false?'activate':'deactivate'}"`,'rowbtn')}${!n&&!linked?btn('ลบถาวร','schoolmanage',`data-id="${s.id}" data-operation="delete"`,'rowbtn danger'):''}</div>`];}))}${administrationHistory('schools')}</section>`;
}
function schoolForm(operation,id){
 if(!isAdmin())throw Error('เฉพาะผู้ดูแลระบบ');const row=operation==='create'?null:data.schools.find(s=>s.id===+id);if(operation!=='create'&&!row)throw Error('ไม่พบสถานศึกษา');schoolTarget={operation,row:row?structuredClone(row):null};
 const title=({create:'เพิ่มหน่วยงาน/สถานศึกษา',update:'แก้ไขหน่วยงาน/สถานศึกษา',deactivate:'ปิดใช้งานหน่วยงาน',activate:'เปิดใช้งานหน่วยงาน',delete:'ลบหน่วยงานถาวร'})[operation];
 modal(title,`<form id="schoolform" class="formgrid">${['create','update'].includes(operation)?input('name','ชื่อหน่วยงาน/สถานศึกษา *',row?.name,'text','required maxlength="200"')+input('province','จังหวัด *',row?.province,'text','required maxlength="100"')+select('unit_type','ประเภทหน่วยงาน',[['college','หน่วยงาน/สถานศึกษา'],['institute','ส่วนกลางสถาบัน']],row?.unit_type||'college'):`<p class="wide notice">${esc(row.name)}${operation==='deactivate'?' — เก็บข้อมูลเดิม แต่หยุดเพิ่มบุคลากรและหยุดสิทธิ์แก้ไขของเจ้าหน้าที่':''}</p>`}${operation==='delete'?`<p class="wide warning">ลบเฉพาะสถานศึกษาที่ไม่มีบุคลากรหรือสิทธิ์อ้างอิง</p>${input('confirm_school_id','กรอกรหัสสถานศึกษาเพื่อยืนยัน',null,'text',`required placeholder="${row.id}"`)}<label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบรายการที่จะลบแล้ว</span></label>`:''}${reasonField()}${formEnd}</form>`);
}
function reasonField(){return `<label class="wide">เหตุผล *<textarea name="reason" required minlength="5" maxlength="1000" rows="3" placeholder="ระบุเหตุผลอย่างน้อย 5 ตัวอักษร"></textarea></label>`;}
function assignmentsPanel(){
 return `<div class="paneltitle"><h2>สิทธิ์เจ้าหน้าที่หน่วยงาน</h2></div><p class="footnote">สร้างบัญชีบุคลากรก่อน แล้วเลือก “กำหนดสิทธิ์” ให้รับผิดชอบทั้งสถานศึกษาหรือเฉพาะรายชื่อ</p>${table(['ผู้รับผิดชอบ','หน่วยงาน/สถานศึกษา','ขอบเขต','สิทธิ์','จัดการ'],(data.school_assignments||[]).map(a=>{const p=data.personnel.find(p=>p.user_id===a.user_id),profile=data.profiles.find(p=>p.id===a.user_id);return [esc(p?.full_name||profile?.username||'บัญชีเดิม'),esc(school(a.school_id)),a.personnel_ids===null?'ทั้งสถานศึกษา':`${a.personnel_ids.length} รายชื่อ`,esc(a.permissions.map(k=>permissionLabels[k]||k).join(' / ')),`<div class="person-actions">${p&&data.schools.find(s=>s.id===a.school_id)?.is_active!==false?btn('แก้ไขสิทธิ์','assignpermissions',`data-id="${esc(p.id)}" data-assignment="${esc(a.id)}"`,'rowbtn'):''}${btn('ถอนสิทธิ์','revokeassignment',`data-id="${esc(a.id)}"`,'rowbtn danger')}</div>`];}))}${administrationHistory('school_assignments')}`;
}
function assignmentForm(personId,assignmentId){
 if(!isAdmin())throw Error('เฉพาะผู้ดูแลระบบ');const p=person(personId),existing=data.school_assignments.find(a=>a.id===assignmentId);if(!p?.user_id)throw Error('กรุณาสร้างบัญชีบุคลากรก่อน');if(data.profiles.find(a=>a.id===p.user_id)?.role==='admin')throw Error('บัญชีผู้ดูแลระบบมีสิทธิ์ส่วนกลางอยู่แล้ว');
 const choices=data.schools.filter(s=>s.is_active!==false);if(!choices.length)throw Error('ยังไม่มีสถานศึกษาที่เปิดใช้งาน');const selected=existing?.school_id||(choices.some(s=>s.id===p.school_id)?p.school_id:choices[0].id);
 assignmentTarget={user_id:p.user_id,existing:existing?structuredClone(existing):null};const permissions=existing?.permissions||['view'];
 modal(existing?'แก้ไขสิทธิ์เจ้าหน้าที่':'มอบหมายเจ้าหน้าที่หน่วยงาน',`<div class="review-person"><strong>${esc(p.full_name)}</strong><span>${esc(data.profiles.find(a=>a.id===p.user_id)?.username||'')}</span></div><form id="assignmentform" class="formgrid">${existing?`<label>สถานศึกษาที่รับผิดชอบ<input value="${esc(school(selected))}" disabled><input type="hidden" name="assignment_school" value="${selected}"></label>`:select('assignment_school','สถานศึกษาที่รับผิดชอบ',choices.map(s=>[s.id,s.name]),selected)}${select('scope','ขอบเขตข้อมูล',[['all','ทั้งสถานศึกษา'],['selected','เฉพาะรายชื่อที่เลือก']],existing?.personnel_ids?'selected':'all')}<fieldset class="wide permission-grid"><legend>การดำเนินการที่อนุญาต</legend><label class="checkrow"><span><input type="checkbox" checked disabled> ดูข้อมูล</span></label>${Object.entries(permissionLabels).filter(([k])=>k!=='view').map(([k,v])=>`<label class="checkrow"><span><input type="checkbox" name="permission" value="${k}" ${permissions.includes(k)?'checked':''}> ${esc(v)}</span></label>`).join('')}</fieldset><div class="wide" id="assignmentpeople"></div><p class="wide footnote">สิทธิ์เพิ่มบุคลากรและนำเข้า Excel ใช้ได้เมื่อรับผิดชอบทั้งสถานศึกษา การแก้ไขทะเบียนและวุฒิการศึกษาแยกสิทธิ์กัน ผู้ใช้ต้องเข้าสู่ระบบใหม่หลังเปลี่ยนสิทธิ์</p>${reasonField()}${formEnd}</form>`);if(existing)updateAssignmentPeople();else assignmentSchoolChanged();
}
function updateAssignmentPeople(){
 const f=$('#assignmentform');if(!f?.elements)return;const schoolId=+f.elements.namedItem('assignment_school').value,selected=f.elements.namedItem('scope').value==='selected';for(const el of f.querySelectorAll('[name="permission"]'))if(['create_personnel','import'].includes(el.value)){el.disabled=selected;if(selected)el.checked=false;}const box=$('#assignmentpeople');if(!selected){box.hidden=true;box.innerHTML='';return;}box.hidden=false;
 const ids=assignmentTarget?.existing?.school_id===schoolId?assignmentTarget.existing.personnel_ids||[]:[];
 box.innerHTML=`<fieldset class="assigned-people"><legend>รายชื่อที่รับผิดชอบ</legend>${data.personnel.filter(p=>p.school_id===schoolId).map(p=>`<label class="checkrow"><span><input type="checkbox" name="assigned_person" value="${esc(p.id)}" ${ids.includes(p.id)?'checked':''}> ${esc(p.full_name)} <small>${esc(p.employee_code)}</small></span></label>`).join('')||'<p>ยังไม่มีบุคลากรในสถานศึกษานี้</p>'}</fieldset>`;
}
function revokeAssignment(id){const a=data.school_assignments.find(a=>a.id===id);if(!isAdmin()||!a)throw Error('ไม่พบสิทธิ์');assignmentTarget={existing:structuredClone(a)};modal('ถอนสิทธิ์เจ้าหน้าที่',`<form id="revokeassignmentform" class="formgrid"><p class="wide notice">ถอนสิทธิ์ใน ${esc(school(a.school_id))} หากไม่มีการมอบหมายอื่น บัญชีจะกลับเป็นบุคลากรที่ดูแลข้อมูลตนเอง</p>${reasonField()}<label class="wide checkrow"><span><input type="checkbox" name="reviewed" required> ตรวจสอบผู้รับผิดชอบและสถานศึกษาแล้ว</span></label>${formEnd}</form>`);}
function administrationHistory(entity){const rows=(data.administration_changes||[]).filter(x=>x.entity===entity).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,15);return rows.length?`<details class="management-history"><summary>ประวัติการเปลี่ยนแปลงล่าสุด</summary>${table(['เวลา','การดำเนินการ','เหตุผล',''],rows.map(x=>[date(x.created_at),esc(x.action),esc(x.reason),btn('รายละเอียด','adminchange',`data-id="${esc(x.id)}"`,'rowbtn')]))}</details>`:'';}
function administrationDetail(id){const r=data.administration_changes.find(r=>r.id===id);if(!isAdmin()||!r)throw Error('ไม่มีสิทธิ์');modal('ประวัติการจัดการ',`<p>${esc(r.action)} · ${date(r.created_at)}</p><p>เหตุผล: ${esc(r.reason)}</p><p>ผู้ดำเนินการ: ${esc(data.profiles.find(p=>p.id===r.actor_id)?.username||r.actor_id)}</p><div class="change-snapshots"><section><h3>ก่อนเปลี่ยนแปลง</h3><pre>${esc(JSON.stringify(r.old_data,null,2))}</pre></section><section><h3>หลังเปลี่ยนแปลง</h3><pre>${esc(JSON.stringify(r.new_data,null,2))}</pre></section></div>`);}
function schoolReferences(){modal('รหัสสถานศึกษาปัจจุบัน',`<p>ใช้ชื่อเต็มในคอลัมน์ หน่วยงาน/สถานศึกษา ของ Excel สถานศึกษาที่ปิดใช้งานจะไม่นำเข้าข้อมูลใหม่</p>${table(['รหัส','หน่วยงาน/สถานศึกษา','จังหวัด','การใช้งาน'],data.schools.map(s=>[s.id,esc(s.name),esc(s.province),s.is_active===false?'ปิดใช้งาน':'ใช้งาน']))}<div class="modalactions">${btn('ดาวน์โหลดแม่แบบตามสิทธิ์ปัจจุบัน','downloadtemplate','','primary')}</div>`);}
async function downloadCurrentTemplate(){
 if(!window.XLSX)throw Error('ตัวช่วย Excel ยังไม่พร้อม กรุณาโหลดหน้าใหม่');const wb=XLSX.utils.book_new(),available=data.schools.filter(s=>s.is_active!==false&&(isAdmin()||schoolAccess(s.id,'import')));
 for(const [name,rows] of templateSheets(available,data.lookups)){const sheet=XLSX.utils.aoa_to_sheet(rows);sheet['!cols']=Array.from({length:Math.max(...rows.map(r=>r.length))},(_,i)=>({wch:name==='คำแนะนำ'?(i?100:30):i===1?45:28}));XLSX.utils.book_append_sheet(wb,sheet,name);}await XLSX.writeFile(wb,`HRVec-Andaman2-v${templateVersion}-Personnel-Template.xlsx`);
}

function updatePersonnelSchoolFields(changed=false){
 const f=$('#personform');if(!f?.elements)return;const id=+f.elements.namedItem('school_id')?.value;const department=f.elements.namedItem('department');if(department){const old=department.value,unit=data.schools.find(s=>s.id===id),names=departmentsFor(unit,data.lookups);if(!changed&&old&&!names.includes(old))names.push(old);department.innerHTML='<option value="">— ไม่ระบุฝ่าย/ส่วนราชการ —</option>'+names.map(n=>`<option value="${esc(n)}" ${n===old?'selected':''}>${esc(n)}</option>`).join('');if(changed&&!names.includes(old))department.value='';department.closest('label').firstChild.textContent=unitType(unit)==='institute'?'ส่วนราชการสถาบัน (เว้นว่างได้)':'ฝ่ายสถานศึกษา (เว้นว่างได้)';}
 if(!isEditor()||editSnapshot)return;const education=schoolAccess(id,'education_write'),cert=schoolAccess(id,'certificates_write');
 for(const el of f.querySelectorAll('[name="highest_education"],[name="education_major"]'))el.disabled=!education;
 const add=f.elements.namedItem('add_certificate');if(add){add.disabled=!cert;if(!cert){add.checked=false;const fields=$('#inlinecertfields');fields.disabled=true;fields.hidden=true;}}
}

function assignmentSchoolChanged(){
 const f=$('#assignmentform');if(!f?.elements||!assignmentTarget)return;const schoolId=+f.elements.namedItem('assignment_school').value;const existing=data.school_assignments.find(a=>a.user_id===assignmentTarget.user_id&&a.school_id===schoolId);assignmentTarget.existing=existing?structuredClone(existing):null;
 f.elements.namedItem('scope').value=existing?.personnel_ids?'selected':'all';for(const el of f.querySelectorAll('[name="permission"]'))el.checked=!!existing?.permissions.includes(el.value);updateAssignmentPeople();
}

function competencyInputs(c={},prefix=''){return `<p class="wide footnote">ใบรับรองสมรรถนะ: ระบุสาขาอาชีพ ระดับ และมาตรฐานตามที่ปรากฏในใบรับรอง ช่องที่ไม่มีข้อมูลเว้นว่างได้</p>`+input(prefix+'occupation','สาขาอาชีพ',c.occupation,'text','maxlength="300"')+input(prefix+'competency_level','ระดับสมรรถนะ / คุณวุฒิวิชาชีพ',c.competency_level,'text','maxlength="300"')+input(prefix+'standard','มาตรฐานอ้างอิง (ถ้ามี)',c.standard,'text','maxlength="300"');}
